package com.example.yuejie;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Real-device entry refresh, real network data, and controlled lifecycle/error seams. */
public final class ReaderUpdateChecks extends DeviceChecks {
 final AtomicInteger requests=new AtomicInteger();CountDownLatch gate=new CountDownLatch(1),started=new CountDownLatch(1),returned=new CountDownLatch(1);boolean fail;JSONArray override;
 @Override public void callActivityOnCreate(Activity activity,Bundle state){super.callActivityOnCreate(activity,state);if(activity instanceof ReaderActivity){ReaderActivity a=(ReaderActivity)activity;ReaderActivity.DirectorySource real=a.directorySource;CountDownLatch release=gate,begin=started,done=returned;boolean failure=fail;JSONArray replacement=override;a.directorySource=(book,force)->{if(!force)return real.fetch(book,false);requests.incrementAndGet();begin.countDown();try{if(!release.await(45,TimeUnit.SECONDS))throw new IOException("test gate timed out");if(failure)throw new IOException("controlled directory failure");return replacement==null?real.fetch(book,true):replacement;}finally{done.countDown();}};}}
 void launch(String book,int at)throws Exception{reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",book).putExtra("book_name","大宋").putExtra("chapter_index",at).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();assertTrue(started.await(10,TimeUnit.SECONDS),"entry refresh started after reader ready");}
 boolean visibleNotice(){return reader.notice!=null&&reader.notice.getVisibility()==View.VISIBLE;}
 void finishReader(){if(reader!=null){ui(()->reader.finish());reader=null;}}
 void resetRequest(boolean failure,JSONArray replacement){fail=failure;override=replacement;gate=new CountDownLatch(1);started=new CountDownLatch(1);returned=new CountDownLatch(1);requests.set(0);}
 void runChecks()throws Exception{
  String book="7616151491132279832";LocalLibrary db=new LocalLibrary(getTargetContext());JSONObject before=db.progress(book);JSONArray original=db.directory(book);Map<String,Long> times=new HashMap<>();try(android.database.Cursor c=db.getReadableDatabase().rawQuery("SELECT id,last_read FROM books",null)){while(c.moveToNext())times.put(c.getString(0),c.getLong(1));}
  try{
   NovelApi api=new NovelApi(getTargetContext(),db);JSONArray live=api.directory(book,true),old=new JSONArray();assertTrue(live.length()>10,"real live directory");int oldCount=live.length()-5;for(int i=0;i<oldCount;i++)old.put(live.getJSONObject(i));db.directory(book,old);launchMain();launch(book,oldCount-1);
   waitFor(()->reader.bookPages!=null,35,"initial progress ready");assertTrue(reader.directory.length()==oldCount&&!reader.busy&&reader.entryDirectoryLoading,"cached reader usable while directory request waits");assertTrue(!visibleNotice(),"entry request has no loading banner");record("cached_reader_before_refresh_returns",oldCount);
   ReaderPaginator current=reader.surface.frame.layout;int anchor=reader.anchor,at=reader.index,token=reader.loadToken;String id=reader.chapter.optString("id");gate.countDown();
   waitFor(()->reader.directory.length()==live.length()&&!reader.entryDirectoryLoading,35,"real live directory appended");waitFor(()->reader.layouts.containsKey(at+1),60,"new next chapter prelaid out");waitFor(()->{for(int i=1;i<=5;i++)if(!reader.library.hasChapter(book,reader.chapterId(at+i)))return false;return true;},90,"five real new chapters cached");
   assertTrue(reader.surface.frame.layout==current&&reader.anchor==anchor&&reader.index==at&&reader.chapter.optString("id").equals(id),"refresh retains exact current layout and offset");assertTrue(reader.surface.frame.totalChapters==live.length(),"frame total refreshed");assertTrue(!visibleNotice(),"successful entry update is silent");record("live_append_preserves_layout_and_prepares_five",new JSONObject().put("old",oldCount).put("live",live.length()).put("next",reader.chapterId(at+1)));shot("entry-update-prepared");
   ui(()->{ReaderSurface.Frame f=reader.surface.frame;reader.commit(new ReaderSurface.Frame(f.id,f.title,at,f.totalChapters,f.layout,f.layout.pages.size()-1));});waitFor(()->reader.adjacent(1)!=null,10,"next frame ready at old end");ReaderActivity.ChapterSource realSource=reader.source;ui(()->{reader.source=(b,c)->{throw new IOException("unexpected synchronous chapter load");};reader.surface.turn(1);});waitFor(()->!reader.surface.animating()&&reader.index==at+1,5,"seamless new chapter turn");assertTrue(reader.loadToken==token&&!visibleNotice()&&requests.get()<=2,"turn uses prepared frame without loading or checking directory");ui(()->reader.source=realSource);waitFor(()->!reader.entryDirectoryLoading,35,"near-end chapter check completes");assertTrue(requests.get()==2,"entry and near-end chapter each check once");record("old_end_turn_uses_prepared_new_chapter",reader.chapter.optString("title"));shot("entry-update-new-chapter");
   ui(()->{reader.prepareNeighbors();reader.refreshDirectoryOnEntry();reader.refreshDirectoryOnEntry();});SystemClock.sleep(65000);assertTrue(requests.get()==2,"no periodic or same chapter directory checks");record("no_repeated_request_after_65_seconds",requests.get());finishReader();
   resetRequest(true,null);db.directory(book,live);launch(book,oldCount-1);gate.countDown();waitFor(()->!reader.entryDirectoryLoading&&reader.bookPages!=null,35,"entry failure completes silently");assertTrue(reader.directory.length()==live.length()&&!reader.busy&&!visibleNotice(),"failure keeps cached body without error banner");ui(()->{reader.refreshDirectoryOnEntry();reader.prepareNeighbors();});assertTrue(requests.get()==1,"entry failure does not loop");record("failed_entry_refresh_keeps_reading_and_does_not_loop",true);finishReader();
   resetRequest(false,live);db.directory(book,old);launch(book,oldCount-1);ReaderActivity paused=reader;ui(()->paused.startActivity(new Intent(paused,MainActivity.class)));waitFor(()->!paused.foreground,5,"reader paused");gate.countDown();assertTrue(returned.await(10,TimeUnit.SECONDS),"late response returned");SystemClock.sleep(500);assertTrue(paused.directory.length()==oldCount&&paused.pendingEntryDirectory==null,"paused reader ignores late directory response");record("pause_discards_late_entry_response",true);finishReader();
   resetRequest(false,live);db.directory(book,old);launch(book,oldCount-1);ui(()->reader.surface.dragging=true);gate.countDown();waitFor(()->!reader.entryDirectoryLoading&&reader.pendingEntryDirectory!=null,10,"response deferred during gesture");assertTrue(reader.directory.length()==oldCount,"directory not swapped during drag");ui(()->{reader.surface.dragging=false;reader.surface.flushVisuals();});assertTrue(reader.directory.length()==live.length(),"gesture idle applies pending directory");record("gesture_defers_directory_until_idle",true);finishReader();
  }finally{gate.countDown();finishReader();if(original!=null)db.directory(book,original);if(before!=null)db.progress(book,before.optString("chapter"),before.optInt("offset"),before.optInt("index"),before.optInt("total"),before.optString("title"));for(Map.Entry<String,Long> item:times.entrySet()){ContentValues values=new ContentValues();values.put("last_read",item.getValue());db.getWritableDatabase().update("books",values,"id=?",new String[]{item.getKey()});}}
  assertTrue(before==null||db.progress(book).toString().equals(before.toString()),"original reading position restored");record("original_position_restored",true);
 }
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"device-evidence");output.mkdirs();Bundle result=new Bundle();Throwable failure=null;try{runChecks();result.putString("stream","PASS "+checks.length()+" checks\n");}catch(Throwable e){failure=e;try{record("failure",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));}try(Writer writer=new OutputStreamWriter(new FileOutputStream(new File(output,"entry-update-results.json")),"UTF-8")){writer.write(new JSONObject().put("device",Build.MODEL).put("success",failure==null).put("checks",checks).toString(2));}catch(Exception ignored){}finish(failure==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
